CREATE TABLE [purchase].[PurchaseInvoices]([PurchaseInvoiceId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_PurchaseInvoices_Id] DEFAULT NEWSEQUENTIALID(),[InvoiceNumber] NVARCHAR(50) NOT NULL,[SupplierId] UNIQUEIDENTIFIER NOT NULL,[SupplierInvoiceNo] NVARCHAR(100) NULL,[InvoiceDate] DATETIMEOFFSET NOT NULL,[DueDate] DATETIMEOFFSET NULL,[WarehouseId] UNIQUEIDENTIFIER NOT NULL,[Subtotal] DECIMAL(18,2) NOT NULL,[DiscountAmount] DECIMAL(18,2) NOT NULL CONSTRAINT [DF_PurchaseInvoices_Discount] DEFAULT 0,[TaxAmount] DECIMAL(18,2) NOT NULL CONSTRAINT [DF_PurchaseInvoices_Tax] DEFAULT 0,[ExpenseAmount] DECIMAL(18,2) NOT NULL CONSTRAINT [DF_PurchaseInvoices_Expense] DEFAULT 0,[RoundOff] DECIMAL(18,2) NOT NULL CONSTRAINT [DF_PurchaseInvoices_Round] DEFAULT 0,[GrandTotal] DECIMAL(18,2) NOT NULL,[PaidAmount] DECIMAL(18,2) NOT NULL CONSTRAINT [DF_PurchaseInvoices_Paid] DEFAULT 0,[BalanceAmount] AS([GrandTotal]-[PaidAmount]) PERSISTED,[Status] NVARCHAR(20) NOT NULL,[Remarks] NVARCHAR(1000) NULL,[IsDeleted] BIT NOT NULL CONSTRAINT [DF_PurchaseInvoices_Deleted] DEFAULT 0,[CreatedOn] DATETIMEOFFSET NOT NULL CONSTRAINT [DF_PurchaseInvoices_Created] DEFAULT SYSUTCDATETIME(),[CreatedBy] NVARCHAR(256) NULL,[ModifiedOn] DATETIMEOFFSET NULL,[ModifiedBy] NVARCHAR(256) NULL,[RowVersion] ROWVERSION NOT NULL,CONSTRAINT [PK_PurchaseInvoices] PRIMARY KEY([PurchaseInvoiceId]),CONSTRAINT [UQ_PurchaseInvoices_Number] UNIQUE([InvoiceNumber]),CONSTRAINT [FK_PurchaseInvoices_Supplier] FOREIGN KEY([SupplierId]) REFERENCES [purchase].[Suppliers]([SupplierId]),CONSTRAINT [FK_PurchaseInvoices_Warehouse] FOREIGN KEY([WarehouseId]) REFERENCES [inventory].[Warehouses]([WarehouseId]),CONSTRAINT [CK_PurchaseInvoices_Status] CHECK([Status] IN('DRAFT','POSTED','PARTIALLY_RETURNED','RETURNED','CANCELLED')));
GO
CREATE UNIQUE INDEX [UX_PurchaseInvoices_SupplierInvoice] ON [purchase].[PurchaseInvoices]([SupplierId],[SupplierInvoiceNo]) WHERE [SupplierInvoiceNo] IS NOT NULL AND [IsDeleted]=0;
GO
CREATE INDEX [IX_PurchaseInvoices_Date] ON [purchase].[PurchaseInvoices]([InvoiceDate] DESC,[Status],[SupplierId]);
